insert into public.tax_form (code, name, description, legal_ref, verified_at, source_key) values
  ('303', 'IVA', null, 'Orden EHA/3786/2008, de 29 de diciembre, por la que se aprueban el modelo 303 Impuesto sobre el Valor Añadido, Autoliquidación, y el modelo 308 Impuesto sobre el Valor Añadido, solicitud de devolución: Recargo de equivalencia, artículo 30 bis del Reglamento del IVA y sujetos pasivos ocasionales y se modifican los Anexos I y II de la Orden EHA/3434/2007, de 23 de noviembre, por la que se aprueban los modelos 322 de autoliquidación mensual, modelo individual, y 353 de autoliquidación mensual, modelo agregado, así como otra normativa tributaria', '2026-10-02', 'orden-modelo-303'),
  ('390', 'Resumen anual del IVA', null, 'Orden EHA/3111/2009, de 5 de noviembre, por la que se aprueba el modelo 390 de declaración-resumen anual del Impuesto sobre el Valor Añadido y se modifica el anexo I de la Orden EHA/1274/2007, de 26 de abril, por la que se aprueban los modelos 036 de Declaración censal de alta, modificación y baja en el Censo de empresarios, profesionales y retenedores y 037 Declaración censal simplificada de alta, modificación y baja en el Censo de empresarios, profesionales y retenedores', '2026-10-02', 'orden-modelo-390'),
  ('111', 'Retenciones', null, 'Orden EHA/586/2011, de 9 de marzo, por la que se aprueba el modelo 111 de autoliquidación de retenciones e ingresos a cuenta del Impuesto sobre la Renta de las Personas Físicas sobre rendimientos del trabajo y de actividades económicas, premios y determinadas ganancias patrimoniales e imputaciones de renta y se modifica otra normativa tributaria', '2026-10-02', 'orden-modelo-111'),
  ('202', 'Pago fraccionado de Sociedades', null, 'Orden HFP/227/2017, de 13 de marzo, por la que se aprueba el modelo 202 para efectuar los pagos fraccionados a cuenta del Impuesto sobre Sociedades y del Impuesto sobre la Renta de no Residentes correspondiente a establecimientos permanentes y entidades en régimen de atribución de rentas constituidas en el extranjero con presencia en territorio español, y el modelo 222 para efectuar los pagos fraccionados a cuenta del Impuesto sobre Sociedades en régimen de consolidación fiscal y se establecen las condiciones generales y el procedimiento para su presentación electrónica', '2026-10-02', 'orden-modelo-202'),
  ('347', 'Operaciones con terceros', null, 'Orden EHA/3012/2008, de 20 de octubre, por la que se aprueba el modelo 347 de Declaración anual de operaciones con terceras personas, así como los diseños físicos y lógicos y el lugar, forma y plazo de presentación', '2026-10-02', 'orden-modelo-347'),
  ('349', 'Operaciones intracomunitarias', null, 'Orden EHA/769/2010, de 18 de marzo, por la que se aprueba el modelo 349 de declaración recapitulativa de operaciones intracomunitarias, así como los diseños físicos y lógicos y el lugar, forma y plazo de presentación, se establecen las condiciones generales y el procedimiento para su presentación telemática, y se modifica la Orden HAC/3625/2003, de 23 de diciembre, por la que se aprueban el modelo 309 de declaración-liquidación no periódica del Impuesto sobre el Valor Añadido, y otras normas tributarias', '2026-10-02', 'orden-modelo-349'),
  ('180', 'Resumen anual de retenciones del alquiler', null, 'Orden de 20 de noviembre de 2000 por la que se aprueban los modelos 115, en pesetas y en euros, de declaración-documento de ingreso, los modelos 180, en pesetas y en euros, del resumen anual de retenciones e ingresos a cuenta sobre determinadas rentas o rendimientos procedentes del arrendamiento o subarrendamiento de inmuebles urbanos del Impuesto sobre la Renta de las Personas Físicas, del Impuesto sobre Sociedades y del Impuesto sobre la Renta de no Residentes, correspondiente a establecimientos permanentes, así como los diseños físicos y lógicos para la sustitución de las hojas interiores del citado modelo 180 por soportes directamente legibles por ordenador y se establecen las condiciones generales y el procedimiento para su presentación telemática', '2026-10-02', 'orden-modelo-180'),
  ('115', 'Retenciones del alquiler', null, 'Orden de 20 de noviembre de 2000 por la que se aprueban los modelos 115, en pesetas y en euros, de declaración-documento de ingreso, los modelos 180, en pesetas y en euros, del resumen anual de retenciones e ingresos a cuenta sobre determinadas rentas o rendimientos procedentes del arrendamiento o subarrendamiento de inmuebles urbanos del Impuesto sobre la Renta de las Personas Físicas, del Impuesto sobre Sociedades y del Impuesto sobre la Renta de no Residentes, correspondiente a establecimientos permanentes, así como los diseños físicos y lógicos para la sustitución de las hojas interiores del citado modelo 180 por soportes directamente legibles por ordenador y se establecen las condiciones generales y el procedimiento para su presentación telemática', '2026-10-02', 'orden-modelo-180'),
  ('130', 'Pago a cuenta del IRPF', null, 'Orden EHA/672/2007, de 19 de marzo, por la que se aprueban los modelos 130 y 131 para la autoliquidación de los pagos fraccionados a cuenta del Impuesto sobre la Renta de las Personas Físicas correspondientes, respectivamente, a actividades económicas en estimacion directa y a actividades económicas en estimación objetiva, el modelo 310 de declaración ordinaria para la autoliquidaciòn del régimen simplificado del Impuesto sobre el Valor Añadido, se determinan el lugar y forma de presentación de los mismos y se modifica en materia de domiciliación bancaria la Orden EHA/3398/2006, de 26 de octubre', '2026-10-02', 'orden-modelo-130')
on conflict (code) do nothing;

